CREATE TRIGGER e03_328_05_tr BEFORE UPDATE OF trace_id ON e01_506_04_tb WHEN OLD.trace_id <> NEW.trace_id BEGIN SELECT RAISE(ABORT, 'e01_506_04_tb.trace_id is immutable'); END;
